// Armoni pregunta: la IA revisa los movimientos, pregunta lo que no está claro y aprende de lo que le contestan.
// pendientes: las preguntas sin responder · revisar: busca movimientos dudosos y arma preguntas · responder: interpreta la respuesta y aprende
const it = $input.first().json;
let b = it.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
if (b.token !== 'mercado-7d41c2a9e05b') return [{ json: { ok: false, accion: 'error', error: 'token' } }];
const accion = ['pendientes', 'revisar', 'responder', 'saltar', 'olvidar'].includes(b.accion) ? b.accion : 'pendientes';
const sd = $getWorkflowStaticData('global');
sd.preguntas = sd.preguntas || []; sd.memoria = sd.memoria || []; sd.ajustes = sd.ajustes || {}; sd.vistos = sd.vistos || {};
// versión 2: antes se confundían movimientos con códigos parecidos; se empieza de nuevo (lo aprendido se conserva)
if (!sd.v2) { sd.v2 = true; sd.preguntas = []; sd.ajustes = {}; sd.vistos = {}; sd.revisado = ''; }
// lo que la familia ya contó (punto de partida de la memoria)
if (!sd.sembrada) { sd.sembrada = true; sd.memoria.push(
  'Cherry es el carro de la mamá de Carlos: el «SOAT cherry» y su «Pago soat cherry» son un favor (ella devolvió la plata), no son gasto ni ingreso de la familia.',
  '«Pago pc Yepes» fue la venta de un computador y la plata quedó para la familia: es ingreso real.',
  'El «Subsidio Comfandi» es plata que le entra a Emanuel (Ema): es ingreso real de la familia.',
  'Las cajitas de Nu son bolsillos de la misma cuenta: mover plata entre ellas no es gasto ni ingreso. Los rendimientos de las cajitas sí son ingreso.'); }
// la app guarda copia de lo aprendido: si el flujo se reinstaló y solo tiene lo inicial, se recupera
if (Array.isArray(b.memoria) && sd.memoria.length <= 4) { b.memoria.slice(0, 150).forEach(t => { t = String(t || '').trim().slice(0, 240); if (t && !sd.memoria.includes(t)) sd.memoria.push(t); }); }
// olvidar un recuerdo que ya no es cierto
if (accion === 'olvidar') { const t = String(b.texto || '').trim(); sd.memoria = sd.memoria.filter(x => x !== t); }
// segunda tanda de lo que la familia ya contó
if (!sd.sembrada2) { sd.sembrada2 = true; sd.memoria.push(
  'Carlos y su esposa Aleja («amor») a veces se pasan plata entre ellos: si Carlos le manda plata a Aleja y ella se la devuelve (ej. «Amor devuelve»), son un ida y vuelta que se cancela: no cuenta como ingreso ni como gasto (clasifícalo "favor"). El salario de Aleja, en cambio, sí es ingreso real.'); }
const p = sd.preguntas.find(q => q.id === String(b.id || ''));
if ((accion === 'responder' || accion === 'saltar') && !p) return [{ json: { ok: false, accion: 'error', error: 'pregunta' } }];
const respuesta = String(b.respuesta || '').trim().slice(0, 600);
if (accion === 'responder' && !respuesta) return [{ json: { ok: false, accion: 'error', error: 'respuesta' } }];
const hoy = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10);
// «revisar» corre como mucho una vez al día (salvo que se pida forzar)
const toca = accion !== 'revisar' || b.forzar || sd.revisado !== hoy;
const dias = Math.min(60, Math.max(1, parseInt(b.dias, 10) || 3));
return [{ json: { ok: true, accion: toca ? accion : 'pendientes', id: p ? p.id : '', respuesta, hoy, dias } }];

const sd = $getWorkflowStaticData('global');
const v = $('Validar').first().json;
if (v.accion === 'saltar') { const p = sd.preguntas.find(q => q.id === v.id); if (p) { p.estado = 'saltada'; p.hasta = new Date(Date.now() + (v.dias || 3) * 864e5).toISOString().slice(0, 10); } }
const hoy = v.hoy || '';
const pend = (sd.preguntas || []).filter(q => q.estado === 'pendiente' || (q.estado === 'saltada' && (q.hasta || '') <= hoy)).slice(0, 5)
  .map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones || [], movs: q.movs || [] }));
// todas las dudas sin resolver (también las que dejaron para después) y las últimas respondidas, para la pantalla «Dudas»
const _sd = $getWorkflowStaticData('global');
const _lista = (_sd.preguntas || []);
const abiertas = _lista.filter(q => q.estado === 'pendiente' || q.estado === 'saltada').map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones || [], movs: q.movs || [], saltada: q.estado === 'saltada', creada: q.creada || '' }));
const hechas = _lista.filter(q => q.estado === 'respondida').slice(-8).reverse().map(q => ({ id: q.id, pregunta: q.pregunta, respuesta: q.respuesta || '', movs: q.movs || [] }));
return [{ json: { abiertas, hechas, saber: _sd.memoria || [], ok: v.ok !== false, error: v.error || null, preguntas: pend, ajustes: sd.ajustes || {}, memoria: (sd.memoria || []).length } }];

// referencia corta y única de cada movimiento: el FINAL del código de Notion (el inicio se repite entre páginas)
const ref = (id) => String(id).replace(/-/g, '').slice(-10);
// Lee una propiedad venga como página completa de Notion (properties) o simplificada de n8n (property_xxx)
const clave = (n) => 'property_' + String(n).toLowerCase().replace(/\s+/g, '_');
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const leer = (it, nombre, tipo) => {
  const pr = it.properties && it.properties[nombre];
  if (pr) {
    if (tipo === 'titulo') return txt(pr.title);
    if (tipo === 'texto') return txt(pr.rich_text);
    if (tipo === 'numero') return pr.number != null ? pr.number : null;
    if (tipo === 'fecha') return pr.date && pr.date.start ? pr.date.start.slice(0, 10) : null;
    if (tipo === 'select') return pr.select ? pr.select.name : (pr.status ? pr.status.name : null);
    if (tipo === 'relacion') return pr.relation && pr.relation[0] ? pr.relation[0].id : null;
  }
  let v = it[clave(nombre)];
  if (v === undefined && tipo === 'titulo') v = it.name;
  if (v === undefined || v === null || v === '') return null;
  if (tipo === 'fecha') { const s = typeof v === 'object' ? (v.start || '') : String(v); return s ? s.slice(0, 10) : null; }
  if (tipo === 'relacion') { const r = Array.isArray(v) ? v[0] : v; return r ? (typeof r === 'object' ? r.id : String(r)) : null; }
  if (tipo === 'numero') return typeof v === 'number' ? v : (Number(v) || null);
  return String(v);
};

const sd = $getWorkflowStaticData('global');
const v = $('Validar').first().json;
sd.revisado = v.hoy;
const desde = new Date(Date.now() - 75 * 864e5).toISOString().slice(0, 10);
const todos = $input.all().map(i => i.json).filter(x => x && x.id).map(x => ({
  id: x.id, fecha: leer(x, 'Fecha', 'fecha') || '', tipo: leer(x, 'Tipo', 'select') || '', cat: leer(x, 'Categoría', 'select') || '',
  monto: leer(x, 'Monto', 'numero') || 0, concepto: leer(x, 'Concepto', 'titulo') || '', notas: leer(x, 'Notas', 'texto') || ''
})).filter(m => m.fecha >= desde);
const yaPreguntados = new Set((sd.preguntas || []).flatMap(q => (q.movs || []).map(m => m.id)));
const nuevos = todos.filter(m => !sd.vistos[m.id] && !yaPreguntados.has(m.id) && !sd.ajustes[m.id]);
nuevos.forEach(m => { sd.vistos[m.id] = v.hoy; });
// no crece sin límite
const ks = Object.keys(sd.vistos); if (ks.length > 3000) ks.slice(0, ks.length - 3000).forEach(k => delete sd.vistos[k]);
if (!nuevos.length) return [{ json: { hay: false } }];
// contexto: los nuevos + los del mismo periodo (para ver duplicados y gasto/ingreso que se cancelan)
const linea = m => [ref(m.id), m.fecha, m.tipo, m.cat, Math.round(m.monto), m.concepto, m.notas].join(' | ');
const prompt = 'MEMORIA (lo que ya aprendiste de esta familia):\n' + ((sd.memoria || []).map(f => '- ' + f).join('\n') || '- (vacía)') +
  '\n\nMOVIMIENTOS NUEVOS (ref | fecha | tipo | categoría | monto | concepto | notas):\n' + nuevos.map(linea).join('\n') +
  '\n\nOTROS MOVIMIENTOS RECIENTES PARA COMPARAR:\n' + todos.filter(m => !nuevos.includes(m)).slice(-120).map(linea).join('\n');
const otros = todos.filter(m => !nuevos.includes(m)).slice(-120);
return [{ json: { hay: true, prompt, nuevos, otros } }];

// referencia corta y única de cada movimiento: el FINAL del código de Notion (el inicio se repite entre páginas)
const ref = (id) => String(id).replace(/-/g, '').slice(-10);
// nunca se le muestran códigos a la familia: cada «ref» se cambia por el nombre del movimiento
const limpia = (t, movs) => { let s = String(t || ''); (movs || []).forEach(m => { s = s.split(ref(m.id)).join('«' + m.concepto + '»'); }); return s.replace(/\s*\(?\b[0-9a-f]{10}\b\)?/g, '').replace(/\s{2,}/g, ' ').trim(); };
const sd = $getWorkflowStaticData('global');
const nuevos = $('Candidatos').first().json.nuevos || [];
const otros = $('Candidatos').first().json.otros || [];
const conocidos = nuevos.concat(otros);
let txt = String($input.first().json.output || '');
const m = txt.match(/\{[\s\S]*\}/);
let out = { preguntas: [] };
try { out = JSON.parse(m ? m[0] : txt); } catch (e) {}
const porId8 = id8 => conocidos.find(x => ref(x.id) === String(id8).replace(/-/g, '').slice(-10));
let n = 0;
for (const q of (out.preguntas || []).slice(0, 4)) {
  const movs = (q.ids || [q.id]).map(porId8).filter(Boolean);
  if (!movs.length || !q.pregunta) continue;
  // los montos que dice la pregunta deben ser de los movimientos que se muestran; si no, se descarta (nunca mostrar otro movimiento)
  const cifras = (String(q.pregunta).match(/\d{1,3}(?:\.\d{3})+/g) || []).map(s => Number(s.replace(/\./g, '')));
  const montos = movs.map(m => Math.round(m.monto));
  const suma = montos.reduce((a, b) => a + b, 0);
  if (cifras.some(c => !montos.includes(c) && c !== suma && !montos.some(a => montos.some(b => a + b === c)))) continue;
  sd.preguntas.push({ id: Date.now().toString(36) + (n++), estado: 'pendiente', pregunta: limpia(q.pregunta, movs).slice(0, 300),
    opciones: (q.opciones || []).map(String).slice(0, 4), motivo: String(q.motivo || '').slice(0, 200), movs, creada: new Date().toISOString() });
}
// lo que la IA ya sabía por la memoria: se aplica sin preguntar
for (const a of (out.ya_se || [])) {
  const mov = porId8(a.id); if (!mov) continue;
  if (['favor', 'traslado', 'duplicado', 'invertido'].includes(a.clasificacion)) sd.ajustes[mov.id] = { clas: a.clasificacion, tipo: mov.tipo, monto: mov.monto, fecha: mov.fecha, cat: mov.cat, concepto: mov.concepto, nota: String(a.nota || 'por lo que ya sé').slice(0, 120) };
}
sd.preguntas = sd.preguntas.slice(-60);
const hoy = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10);
const pend = sd.preguntas.filter(q => q.estado === 'pendiente' || (q.estado === 'saltada' && (q.hasta || '') <= hoy)).slice(0, 5).map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones, movs: q.movs }));
// todas las dudas sin resolver (también las que dejaron para después) y las últimas respondidas, para la pantalla «Dudas»
const _sd = $getWorkflowStaticData('global');
const _lista = (_sd.preguntas || []);
const abiertas = _lista.filter(q => q.estado === 'pendiente' || q.estado === 'saltada').map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones || [], movs: q.movs || [], saltada: q.estado === 'saltada', creada: q.creada || '' }));
const hechas = _lista.filter(q => q.estado === 'respondida').slice(-8).reverse().map(q => ({ id: q.id, pregunta: q.pregunta, respuesta: q.respuesta || '', movs: q.movs || [] }));
return [{ json: { abiertas, hechas, saber: _sd.memoria || [], ok: true, preguntas: pend, ajustes: sd.ajustes, memoria: sd.memoria.length } }];

// referencia corta y única de cada movimiento: el FINAL del código de Notion (el inicio se repite entre páginas)
const ref = (id) => String(id).replace(/-/g, '').slice(-10);
const sd = $getWorkflowStaticData('global');
const v = $('Validar').first().json;
const p = sd.preguntas.find(q => q.id === v.id);
const linea = m => [ref(m.id), m.fecha, m.tipo, m.cat, Math.round(m.monto), m.concepto, m.notas].join(' | ');
const prompt = 'MEMORIA:\n' + ((sd.memoria || []).map(f => '- ' + f).join('\n') || '- (vacía)') +
  '\n\nPREGUNTA QUE HICISTE: ' + p.pregunta + '\nMOVIMIENTOS (ref | fecha | tipo | categoría | monto | concepto | notas):\n' + p.movs.map(linea).join('\n') +
  '\n\nRESPUESTA DE LA FAMILIA: ' + v.respuesta;
return [{ json: { prompt } }];

// referencia corta y única de cada movimiento: el FINAL del código de Notion (el inicio se repite entre páginas)
const ref = (id) => String(id).replace(/-/g, '').slice(-10);
// nunca se le muestran códigos a la familia: cada «ref» se cambia por el nombre del movimiento
const limpia = (t, movs) => { let s = String(t || ''); (movs || []).forEach(m => { s = s.split(ref(m.id)).join('«' + m.concepto + '»'); }); return s.replace(/\s*\(?\b[0-9a-f]{10}\b\)?/g, '').replace(/\s{2,}/g, ' ').trim(); };
const sd = $getWorkflowStaticData('global');
const v = $('Validar').first().json;
const p = sd.preguntas.find(q => q.id === v.id);
let txt = String($input.first().json.output || '');
const m = txt.match(/\{[\s\S]*\}/);
let r = {};
try { r = JSON.parse(m ? m[0] : txt); } catch (e) {}
const validas = ['real', 'favor', 'traslado', 'duplicado', 'invertido'];
const porId8 = id8 => p.movs.find(x => ref(x.id) === String(id8).replace(/-/g, '').slice(-10));
for (const a of (r.movimientos || [])) {
  const mov = porId8(a.id); const clas = validas.includes(a.clasificacion) ? a.clasificacion : null;
  if (!mov || !clas) continue;
  if (clas === 'real') { delete sd.ajustes[mov.id]; continue; }
  sd.ajustes[mov.id] = { clas, tipo: mov.tipo, monto: mov.monto, fecha: mov.fecha, cat: mov.cat, concepto: mov.concepto, nota: String(a.nota || '').slice(0, 120) };
}
for (const f of (r.aprender || [])) { const t = String(f || '').trim().slice(0, 240); if (t && !sd.memoria.includes(t)) sd.memoria.push(t); }
sd.memoria = sd.memoria.length > 150 ? sd.memoria.slice(0, 4).concat(sd.memoria.slice(-146)) : sd.memoria;
if (r.repreguntar) { p.pregunta = limpia(r.repreguntar, p.movs).slice(0, 300); p.opciones = []; p.estado = 'pendiente'; }
else { p.estado = 'respondida'; p.respuesta = v.respuesta; }
const hoy = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10);
const pend = sd.preguntas.filter(q => q.estado === 'pendiente' || (q.estado === 'saltada' && (q.hasta || '') <= hoy)).slice(0, 5).map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones, movs: q.movs }));
// todas las dudas sin resolver (también las que dejaron para después) y las últimas respondidas, para la pantalla «Dudas»
const _sd = $getWorkflowStaticData('global');
const _lista = (_sd.preguntas || []);
const abiertas = _lista.filter(q => q.estado === 'pendiente' || q.estado === 'saltada').map(q => ({ id: q.id, pregunta: q.pregunta, opciones: q.opciones || [], movs: q.movs || [], saltada: q.estado === 'saltada', creada: q.creada || '' }));
const hechas = _lista.filter(q => q.estado === 'respondida').slice(-8).reverse().map(q => ({ id: q.id, pregunta: q.pregunta, respuesta: q.respuesta || '', movs: q.movs || [] }));
return [{ json: { abiertas, hechas, saber: _sd.memoria || [], ok: true, mensaje: limpia(r.mensaje || '¡Listo, ya lo aprendí!', p.movs).slice(0, 300), sigue: !!r.repreguntar, preguntas: pend, ajustes: sd.ajustes, memoria: sd.memoria.length } }];
